    @EventHandler( payloadType=CreatePromotionEvent.class )
    public void handle( CreatePromotionEvent event) {
	    LOGGER.info("handling CreatePromotionEvent - " + event );
	    Promotion entity = new Promotion();
            entity.setPromotionId( event.getPromotionId() );
            entity.setName( event.getName() );
            entity.setCode( event.getCode() );
            entity.setValue( event.getValue() );
            entity.setStartDate( event.getStartDate() );
            entity.setEndDate( event.getEndDate() );
            entity.setAsStackable( event.getAsStackable() );
            entity.setMaxRedemptions( event.getMaxRedemptions() );
            entity.setPromotionType( event.getPromotionType() );
            entity.setDiscountType( event.getDiscountType() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllPromotion( entity );
    }

