    /**
     * Method to retrieve the Promotion via an PromotionPrimaryKey.
     * @param 	id Long
     * @return 	Promotion
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Promotion handle( FindPromotionQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getPromotionId() );
    }
    
    /**
     * Method to retrieve a collection of all Promotions
     *
     * @param	query	FindAllPromotionQuery 
     * @return 	List<Promotion> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Promotion> handle( FindAllPromotionQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindPromotion,
 * but only if the id matches
 *
 * @param		entity	Promotion
 */
	protected void emitFindPromotion( Promotion entity ) {
		LOGGER.info("handling emitFindPromotion" );
		
	    queryUpdateEmitter.emit(FindPromotionQuery.class,
	                            query -> query.getFilter().getPromotionId().equals(entity.getPromotionId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllPromotion
	 * 
	 * @param		entity	Promotion
	 */
	protected void emitFindAllPromotion( Promotion entity ) {
		LOGGER.info("handling emitFindAllPromotion" );
		
	    queryUpdateEmitter.emit(FindAllPromotionQuery.class,
	                            query -> true,
	                            entity);
	}

